from __future__ import annotations
from .canonical import with_digest
SECURITY_CONTROLS=[
('INPUT_PACKAGE_INTEGRITY','INTEGRITY','PREVENTIVE',True),('IDENTITY_AND_LINEAGE_BINDING','IDENTITY','PREVENTIVE',True),('LEAST_PRIVILEGE_CAPABILITIES','AUTHORITY','PREVENTIVE',True),('NETWORK_EGRESS_DENY','NETWORK','PREVENTIVE',True),('SECRET_MATERIAL_ABSENCE','SECRETS','PREVENTIVE',True),('PRODUCTION_KEY_ACCESS_DENY','KEY_CUSTODY','PREVENTIVE',True),('SIGNING_CUSTODY_INTERFACE','KEY_CUSTODY','PREVENTIVE',True),('SUPPLY_CHAIN_INVENTORY','SUPPLY_CHAIN','DETECTIVE',True),('REFERENCE_SBOM','SUPPLY_CHAIN','DETECTIVE',True),('DEPENDENCY_RECALL_GRAPH','SUPPLY_CHAIN','RESPONSIVE',True),('REPRODUCIBLE_BUILD_EVIDENCE','BUILD','DETECTIVE',True),('STATIC_CODE_SCAN','CODE_SECURITY','DETECTIVE',True),('SECRET_SCAN','SECRETS','DETECTIVE',True),('MQL5_FORBIDDEN_API_SCAN','RUNTIME','DETECTIVE',True),('PATH_TRAVERSAL_DEFENSE','FILESYSTEM','PREVENTIVE',True),('SYMLINK_SUBSTITUTION_DEFENSE','FILESYSTEM','PREVENTIVE',True),('RUNTIME_TCB_MINIMIZATION','TCB','PREVENTIVE',True),('PLUGIN_CAPABILITY_SANDBOX','TCB','PREVENTIVE',True),('AUDIT_HASH_CHAIN','AUDIT','DETECTIVE',True),('NON_REPUDIATION_INTERFACE','AUDIT','DETECTIVE',True),('OPERATOR_SEPARATION','OPERATIONS','PREVENTIVE',True),('PRIVILEGED_WORKSTATION_ASSURANCE','OPERATIONS','PREVENTIVE',True),('INCIDENT_RESPONSE_PLAYBOOK','RESPONSE','RESPONSIVE',True),('INCIDENT_TABLETOP_EVIDENCE','RESPONSE','RESPONSIVE',True),('REVOCATION_AND_QUARANTINE','RESPONSE','RESPONSIVE',True),('BACKUP_RECOVERY_TEST','RESILIENCE','RESPONSIVE',True),('SECURITY_MONITORING_INTEGRATION','MONITORING','DETECTIVE',True),('RED_TEAM_VALIDATION','ASSURANCE','DETECTIVE',True),('DATA_CLASSIFICATION','DATA','PREVENTIVE',True),('ARTIFACT_ENCRYPTION_AND_KEY_ROTATION','DATA','PREVENTIVE',True),('CI_BRANCH_PROTECTION','CI_CD','PREVENTIVE',True),('BROKER_AND_CAPITAL_ISOLATION','CAPITAL','PREVENTIVE',True),('KILL_SWITCH_AND_SAFE_SHUTDOWN','CAPITAL','RESPONSIVE',True)]
THREATS=[
('TAMPERED_UPSTREAM_PACKAGE','INTEGRITY','CRITICAL'),('FORGED_MANIFEST_OR_RECEIPT','INTEGRITY','HIGH'),('RUNTIME_CANDIDATE_INVENTION','AUTHORITY','CRITICAL'),('PRODUCTION_KEY_EXFILTRATION','KEY_CUSTODY','CRITICAL'),('SECRET_INJECTION_IN_ARTIFACT','SECRETS','CRITICAL'),('PATH_TRAVERSAL_OR_SYMLINK_SWAP','FILESYSTEM','HIGH'),('DEPENDENCY_SUPPLY_CHAIN_COMPROMISE','SUPPLY_CHAIN','CRITICAL'),('ARBITRARY_PLUGIN_OR_CODE_EXECUTION','TCB','CRITICAL'),('NETWORK_EGRESS_EXFILTRATION','NETWORK','CRITICAL'),('OPERATOR_COLLUSION_OR_SELF_APPROVAL','OPERATIONS','CRITICAL'),('AUDIT_LEDGER_TAMPERING','AUDIT','HIGH'),('CI_RUNNER_OR_BRANCH_COMPROMISE','CI_CD','CRITICAL'),('INCIDENT_RESPONSE_FAILURE','RESPONSE','HIGH'),('BROKER_OR_CAPITAL_BOUNDARY_BYPASS','CAPITAL','CRITICAL')]
READINESS_STATES=['SECURITY_HARDENING_FAILED','NON_PRODUCTION_SECURITY_BASELINE','PRODUCTION_SECURITY_REVIEW_ELIGIBLE_NOT_AUTHORIZED']
def security_control_registry()->dict:
    controls=[{'control_id':i,'version':'1.0.0','domain':d,'control_class':c,'blocks_production':b,'unknown_blocks_production':True} for i,d,c,b in SECURITY_CONTROLS]
    return with_digest({'schema_version':'1.0.0','registry_id':'ACL12_SECURITY_CONTROL_REGISTRY_V1','closed':True,'control_count':len(controls),'controls':controls},'registry_digest')
def threat_registry()->dict:
    items=[{'threat_id':i,'domain':d,'inherent_severity':s,'version':'1.0.0'} for i,d,s in THREATS]
    return with_digest({'schema_version':'1.0.0','registry_id':'ACL12_THREAT_REGISTRY_V1','closed':True,'threat_count':len(items),'threats':items},'registry_digest')
def readiness_state_registry()->dict:
    states=[{'state_id':x,'version':'1.0.0','live_authority':False,'capital_authority':False} for x in READINESS_STATES]
    return with_digest({'schema_version':'1.0.0','registry_id':'ACL12_SECURITY_READINESS_STATE_REGISTRY_V1','closed':True,'state_count':len(states),'states':states},'registry_digest')
